import csv

def load_data(filename):
    try:
        with open(filename, 'r', newline='') as f:
            reader = csv.reader(f)
            return list(reader)
    except FileNotFoundError:
        print(f'Error: The file {filename} was not found.')
        return []

result = load_data('missing.csv')
print(result)

