import csv
import json

def csv_to_json_large_events(input_path, output_path):
    events = []
    with open(input_path, 'r') as infile:
        reader = csv.DictReader(infile)
        for row in reader:
            if int(row['attendees']) > 50:
                events.append({
                    'event_id': row['event_id'],
                    'name': row['name'],
                    'attendees': int(row['attendees'])
                })

    with open(output_path, 'w') as outfile:
        json.dump(events, outfile, indent=2)

csv_to_json_large_events('events.csv', 'large_events.json')

